package org.firstinspires.ftc.teamcode;

import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;
import com.qualcomm.robotcore.hardware.DcMotor;

@TeleOp(name = "Lesson: One Motor (Linear)", group = "Lessons")
public class OneMotorLinear extends LinearOpMode {
    @Override
    public void runOpMode() {
        // "motor" must match the name in the ACTIVE robot configuration (case-sensitive)
        DcMotor motor = hardwareMap.get(DcMotor.class, "motor");

        telemetry.addData("Status", "Initialized");
        telemetry.update();

        waitForStart();               // INIT phase ends when the driver presses START

        while (opModeIsActive()) {    // runs until STOP (or end of match)
            double power = gamepad1.a ? 0.5 : 0.0;   // hold A to run at half power
            motor.setPower(power);

            telemetry.addData("A held", gamepad1.a);
            telemetry.addData("Motor power", power);
            telemetry.update();       // REQUIRED in LinearOpMode or nothing shows on the DS
        }
    }
}

package org.firstinspires.ftc.teamcode;

import com.qualcomm.robotcore.eventloop.opmode.OpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;
import com.qualcomm.robotcore.hardware.DcMotor;

@TeleOp(name = "Lesson: One Motor (Iterative)", group = "Lessons")
public class OneMotorIterative extends OpMode {
    private DcMotor motor;

    @Override
    public void init() {              // once, when INIT is pressed (abstract: must implement)
        motor = hardwareMap.get(DcMotor.class, "motor");
        telemetry.addData("Status", "Initialized");
    }

    @Override
    public void init_loop() { }       // repeatedly between INIT and START (optional)

    @Override
    public void start() { }           // once, when START is pressed (optional)

    @Override
    public void loop() {              // repeatedly until STOP (abstract: must implement)
        double power = gamepad1.a ? 0.5 : 0.0;
        motor.setPower(power);
        telemetry.addData("A held", gamepad1.a);
        telemetry.addData("Motor power", power);
        // no telemetry.update(): loop-based OpModes send telemetry automatically after loop()/init_loop()
    }

    @Override
    public void stop() { }            // once after STOP (optional; hardware control is limited here)
}

// inside runOpMode() of a LinearOpMode, after hardwareMap.get(...)
boolean running = false;
waitForStart();
while (opModeIsActive()) {
    boolean aPressed = gamepad1.aWasPressed();   // true ONCE per press; call it once per loop and store it
    if (aPressed) {
        running = !running;
    }
    motor.setPower(running ? 0.5 : 0.0);
    telemetry.addData("Running", running);
    telemetry.update();
}

