package org.firstinspires.ftc.teamcode;

import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;
import com.qualcomm.robotcore.hardware.DcMotor;

@TeleOp(name = "Mecanum Robot-Centric")
public class MecanumRobotCentric extends LinearOpMode {
    @Override
    public void runOpMode() {
        DcMotor fl = hardwareMap.get(DcMotor.class, "front_left_drive");
        DcMotor bl = hardwareMap.get(DcMotor.class, "back_left_drive");
        DcMotor fr = hardwareMap.get(DcMotor.class, "front_right_drive");
        DcMotor br = hardwareMap.get(DcMotor.class, "back_right_drive");

        // One side must be reversed. The SDK samples reverse the LEFT side; gm0 reverses the RIGHT.
        // Test: push left stick forward -> all wheels should spin forward. If not, flip the other side.
        fl.setDirection(DcMotor.Direction.REVERSE);
        bl.setDirection(DcMotor.Direction.REVERSE);
        for (DcMotor m : new DcMotor[]{fl, bl, fr, br}) {
            m.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);
            m.setMode(DcMotor.RunMode.RUN_WITHOUT_ENCODER);
        }

        waitForStart();
        while (opModeIsActive()) {
            double y  = -gamepad1.left_stick_y;       // stick up is negative, so negate
            double x  =  gamepad1.left_stick_x * 1.1; // counteract imperfect strafing
            double rx =  gamepad1.right_stick_x;      // turn

            // Keep the power ratios when any wheel would exceed |1|
            double d = Math.max(Math.abs(y) + Math.abs(x) + Math.abs(rx), 1);
            fl.setPower((y + x + rx) / d);
            bl.setPower((y - x + rx) / d);
            fr.setPower((y - x - rx) / d);
            br.setPower((y + x - rx) / d);

            telemetry.addData("y/x/rx", "%.2f %.2f %.2f", y, x, rx);
            telemetry.update();
        }
    }
}

package org.firstinspires.ftc.teamcode;

import com.qualcomm.robotcore.eventloop.opmode.Autonomous;
import com.qualcomm.robotcore.eventloop.opmode.LinearOpMode;
import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.util.ElapsedTime;

@Autonomous(name = "Drive Forward By Encoder")
public class DriveByEncoder extends LinearOpMode {
    // Look these up for YOUR motor/wheel. Example: goBILDA 312 RPM Yellow Jacket ~537.7 ticks/rev, 104 mm wheels.
    static final double TICKS_PER_REV = 537.7;
    static final double WHEEL_DIAMETER_IN = 104.0 / 25.4;
    static final double TICKS_PER_INCH = TICKS_PER_REV / (WHEEL_DIAMETER_IN * Math.PI);

    private DcMotor fl, fr, bl, br;

    @Override
    public void runOpMode() {
        fl = hardwareMap.get(DcMotor.class, "front_left_drive");
        fr = hardwareMap.get(DcMotor.class, "front_right_drive");
        bl = hardwareMap.get(DcMotor.class, "back_left_drive");
        br = hardwareMap.get(DcMotor.class, "back_right_drive");
        fl.setDirection(DcMotor.Direction.REVERSE);
        bl.setDirection(DcMotor.Direction.REVERSE);
        for (DcMotor m : new DcMotor[]{fl, fr, bl, br}) {
            m.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);
            m.setMode(DcMotor.RunMode.STOP_AND_RESET_ENCODER); // encoders do NOT reset on their own
        }
        waitForStart();
        driveInches(24, 0.5, 4.0);
        driveInches(-12, 0.5, 3.0);
    }

    private void driveInches(double inches, double power, double timeoutS) {
        int ticks = (int) Math.round(inches * TICKS_PER_INCH);
        DcMotor[] all = {fl, fr, bl, br};
        for (DcMotor m : all) {
            m.setTargetPosition(m.getCurrentPosition() + ticks); // 1) target FIRST
            m.setMode(DcMotor.RunMode.RUN_TO_POSITION);         // 2) then mode (reverse order throws)
            m.setPower(Math.abs(power));                         // 3) unsigned power; hub picks direction
        }
        ElapsedTime t = new ElapsedTime();
        while (opModeIsActive() && t.seconds() < timeoutS
                && (fl.isBusy() || fr.isBusy() || bl.isBusy() || br.isBusy())) {
            telemetry.addData("FL", "%d / %d", fl.getCurrentPosition(), fl.getTargetPosition());
            telemetry.update();
        }
        for (DcMotor m : all) {
            m.setPower(0);
            m.setMode(DcMotor.RunMode.RUN_USING_ENCODER);
        }
    }
}

package org.firstinspires.ftc.teamcode;

import com.qualcomm.robotcore.eventloop.opmode.OpMode;
import com.qualcomm.robotcore.eventloop.opmode.TeleOp;
import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.hardware.DcMotorEx;
import com.qualcomm.robotcore.util.ElapsedTime;
import com.qualcomm.robotcore.util.Range;

@TeleOp(name = "Lift PID Demo")
public class LiftPidDemo extends OpMode {
    // Tune in this order: kG (hold against gravity with P=0), then kP, then kD; kI last if ever.
    public static double kP = 0.005, kI = 0.0, kD = 0.0002, kG = 0.08;
    public static int LOW = 0, HIGH = 1500;   // encoder ticks

    private DcMotorEx lift;
    private final ElapsedTime timer = new ElapsedTime();
    private double integral = 0, lastError = 0;
    private int target = LOW;

    @Override public void init() {
        lift = hardwareMap.get(DcMotorEx.class, "lift");
        lift.setZeroPowerBehavior(DcMotor.ZeroPowerBehavior.BRAKE);
        lift.setMode(DcMotor.RunMode.STOP_AND_RESET_ENCODER);
        lift.setMode(DcMotor.RunMode.RUN_WITHOUT_ENCODER); // we close the loop; the encoder still counts
    }

    @Override public void start() { timer.reset(); }

    @Override public void loop() {
        int newTarget = target;
        if (gamepad1.a) newTarget = LOW;
        if (gamepad1.y) newTarget = HIGH;
        if (newTarget != target) { target = newTarget; integral = 0; } // reset I on setpoint change

        double dt = timer.seconds();
        timer.reset();
        int pos = lift.getCurrentPosition();
        double error = target - pos;

        integral = Range.clip(integral + error * dt, -500, 500);     // anti-windup clamp
        double derivative = dt > 0 ? (error - lastError) / dt : 0;
        lastError = error;

        // Lift: constant gravity term. Arm: replace kG with kCos * Math.cos(angleRadians).
        double power = kP * error + kI * integral + kD * derivative + kG;
        lift.setPower(Range.clip(power, -1, 1));

        telemetry.addData("target", target);
        telemetry.addData("pos", pos);
        telemetry.addData("power", "%.3f", power);
        telemetry.addData("loop ms", "%.1f", dt * 1000);
    }
}

