@Autonomous(name = "Pedro3 Two Path Auto")
public class TwoPathAuto extends OpMode {
    private Follower follower;
    private final PoseFactory p = PoseFactory.degrees();
    private final Pose startPose = p.of(24, 24, 0);   // Pedro coordinates, not FTC official
    private final Pose scorePose = p.of(48, 48, 90);
    private final Pose parkPose  = p.of(72, 48, 90);
    private int step = 0;

    @Override public void init() {
        follower = Constants.create(hardwareMap);  // from the tuned Constants file
        follower.setPose(startPose);
        follower.update();
    }

    @Override public void start() {
        follower.follow(line(startPose, scorePose).linear(startPose, scorePose));
        step = 1;
    }

    @Override public void loop() {
        follower.update();                      // every loop, no exceptions
        switch (step) {
            case 1:
                if (!follower.isBusy()) {       // arrived and settled
                    // start a NON-blocking mechanism action here
                    follower.follow(line(scorePose, parkPose).linear(scorePose, parkPose));
                    step = 2;
                }
                break;
            case 2:
                if (!follower.isBusy()) step = 3;
                break;
        }
        telemetry.addData("step", step);
        telemetry.addData("x", follower.pose().x());
        telemetry.addData("y", follower.pose().y());
        telemetry.addData("heading", Math.toDegrees(follower.pose().heading()));
    }
}

