@TeleOp(name = "Intake (time-based)")
public class IntakeLinear extends LinearOpMode {
    @Override
    public void runOpMode() {
        DcMotor motor = hardwareMap.get(DcMotor.class, "intake");

        waitForStart();

        while (opModeIsActive()) {
            if (gamepad1.a) {
                motor.setPower(0.8);
            } else {
                motor.setPower(0);
            }
        }
    }
}

