@TeleOp(name = "Intake (Ivy)")
public class IntakeIvy extends LinearOpMode {
    @Override
    public void runOpMode() {
        Scheduler.reset();                 // static scheduler: clear leftovers
        Intake intake = new Intake(hardwareMap);
        waitForStart();
        while (opModeIsActive()) {
            if (gamepad1.aWasPressed())  Scheduler.schedule(intake.runIn());
            if (gamepad1.aWasReleased()) Scheduler.schedule(intake.stop()); // OVERRIDE interrupts runIn
            Scheduler.execute();           // one scheduler cycle per loop
        }
    }
}
